namespace Acme\Http\Consolidated;

trait RateLimiterTrait
{
    protected array $requestCounts = [];
    protected int $limit = 100;

    public function assertWithinLimit(string $key): void
    {
        $count = $this->getRequestCount($key);
        if ($count >= $this->limit) {
            throw new \RuntimeException('Rate limit exceeded', 429);
        }
        $this->incrementRequestCount($key);
    }

    protected function getRequestCount(string $key): int
    {
        return $this->requestCounts[$key] ?? 0;
    }

    protected function incrementRequestCount(string $key): void
    {
        $this->requestCounts[$key] = $this->getRequestCount($key) + 1;
    }

    public function setLimit(int $limit): void
    {
        $this->limit = $limit;
    }
