namespace Acme\Logging\Consolidated;

abstract class AbstractLogger
{
    protected int $minLevel;

    public function __construct(int $minLevel = self::INFO)
    {
        $this->minLevel = $minLevel;
    }

    protected function shouldLog(int $level): bool
    {
        return $level >= $this->minLevel;
    }

    protected function format(int $level, string $message): string
    {
        $timestamp = date('Y-m-d H:i:s');
        $levelName = $this->getLevelName($level);
        return "[{$timestamp}] {$levelName}: {$message}";
    }

    protected function getLevelName(int $level): string
    {
        return match($level) {
            self::DEBUG => 'DEBUG',
            self::INFO => 'INFO',
            self::WARNING => 'WARNING',
            self::ERROR => 'ERROR',
            default => 'UNKNOWN',
        };
    }

    abstract protected function write(string $formatted): void;

    public function log(int $level, string $message): void
    {
        if (!$this->shouldLog($level)) {
            return;
        }
        $this->write($this->format($level, $message));
    }

    public const DEBUG = 0;
    public const INFO = 1;
    public const WARNING = 2;
    public const ERROR = 3;
}

